```openscad
// T-shaped extrusion nut / spacer - a T cross-section (flange + neck) with a central screw hole,
// sliding in an aluminium extrusion slot along X. NOVEL general part.
//

flange_w   = 10;   // flange width (Y)
flange_t   = 2.5;  // flange thickness (Z)
neck_w     = 6;    // neck width (Y)
neck_h     = 6.5;  // neck height above flange top (Z)
len        = 10;   // part length along X
screw_d    = 3.4;  // central screw hole diameter
eps        = 0.5;  // cutter overshoot

$fn = 64;

total_h = flange_t + neck_h;

difference() {
    union() {
        // flange
        translate([-len/2, -flange_w/2, 0]) cube([len, flange_w, flange_t]);
        // neck
        translate([-neck_w/2, 0, flange_t]) cube([neck_w, len, neck_h]);
    }
    // through hole
    translate([0, 0, -eps]) cylinder(d = screw_d, h = total_h + 2*eps);
}
```

```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on XY plane, neck upward (+Z)

$fn = 64;

// ---- Dimensions (mm) ----
nut_length    = 10;    // length along X
flange_width  = 10;    // bottom flange width (Y)
flange_height = 2.5;   // flange thickness, z = 0 .. 2.5
neck_width    = 6;     // neck width (Y), centred
total_height  = 6.5;   // top of neck (z)
hole_d        = 3.4;   // vertical screw clearance hole diameter
eps           = 0.5;   // overshoot for clean boolean cuts

difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_height]);

        // Neck (overlaps flange slightly for a clean union)
        translate([-nut_length/2, -neck_width/2, flange_height - 0.01])
            cube([nut_length, neck_width, total_height - flange_height + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = total_height + 2*eps);
}
```

