```openscad
// T-shaped extrusion nut / spacer - a T cross-section (flange + neck) with a central screw hole,
// sliding in the slot of an aluminium extrusion along X. NOVEL general part.
//

flange_w   = 14;   // flange width (Y)
flange_t   = 2.5;  // flange thickness (Z)
neck_w     = 7;    // neck width (Y)
height     = 5.5;  // total height (Z)
length     = 12;   // length along X
screw_d    = 4.5;  // screw hole diameter
eps        = 0.5;  // cutter overshoot

$fn = 64;

difference() {
    union() {
        // flange: z = 0..2.5, y = -7..7, x = -6..6
        cube([length, flange_w, flange_t]);
        // neck: centred on flange, y = -3.5..3.5, z = 2.5..5.5
        translate([0, -flange_w/2 + neck_w/2, flange_t])
            cube([length, neck_w, height - flange_t]);
    }
    // vertical screw hole through the centre
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = height + 2 * eps);
}
```

```openscad
// T-slot nut for aluminium extrusion
// Print orientation: flange down on the bed (z = 0), neck up (+Z)

// ---------- Dimensions (mm) ----------
nut_length      = 12;    // length along X
flange_width    = 14;    // bottom flange width (Y)
flange_height   = 2.5;   // flange thickness, z = 0 .. 2.5
neck_width      = 7;     // neck width (Y), centred
total_height    = 5.5;   // top of neck (z)
hole_d          = 4.5;   // vertical screw hole diameter
cut_extra       = 0.5;   // overshoot for cutting shapes

$fn = 64;

// ---------- Model ----------
difference() {
    union() {
        // Bottom flange
        translate([-nut_length/2, -flange_width/2, 0])
            cube([nut_length, flange_width, flange_height]);

        // Neck (overlaps flange slightly for a clean union)
        translate([-nut_length/2, -neck_width/2, flange_height - 0.01])
            cube([nut_length, neck_width, total_height - flange_height + 0.01]);
    }

    // Vertical screw hole through the centre
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = total_height + 2*cut_extra);
}
