// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 120;   // plate length along X
plate_wid      = 80;    // plate width along Y
plate_thk      = 3;     // plate thickness (z = 0 to 3)

rib_thk        = 3;     // rib thickness along X
rib_h          = 5;     // rib height above plate (z = 3 to 8)
rib_count      = 3;     // number of ribs
rib_pitch      = 30;    // centre-to-centre spacing of ribs
rib_offset     = 30;    // centre of outer rib from plate end

eps            = 0.5;   // overcut for clean boolean differences
$fn            = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_top_z      = plate_thk + rib_h;   // top of ribs (z = 8)
plate_bot_z    = plate_thk;          // top of plate / bottom of ribs (z = 3)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on their respective X positions, running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = (i - (rib_count - 1)/2) * rib_pitch + rib_offset * (i < 1 || i > rib_count - 2);
        translate([x_c - rib_thk/2, -plate_wid/2, plate_bot_z])
            cube([rib_thk, plate_wid, rib_h + eps]); // extend past top face
    }
}
