```openscad
// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 80;   // plate length along X
plate_wid   = 80;   // plate width along Y
plate_thk   = 2;    // plate thickness (z = 0 to 2)

rib_thk     = 3;    // rib thickness along X
rib_h       = 5;    // rib height above plate (z = 2 to 7)
rib_count   = 3;    // number of ribs

rib_pitch   = 20;   // centre-to-centre spacing of ribs along X
rib_offset  = 20;   // centre of outer rib from nearest plate end

eps         = 0.5;  // overcut for clean boolean differences
$fn         = 64;   // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_top_z   = plate_thk + rib_h;   // top of ribs (z = 7)
plate_bot_z = plate_thk;          // top of plate (z = 2)

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y, centred on their X positions
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch - (rib_count - 1) * rib_pitch / 2;
        // Outer ribs placed rib_offset from the plate ends
        if (i == 0 || i == rib_count - 1)
            x_c += sign(i - (rib_count - 1)/2) * (rib_offset - plate_len/2 + rib_pitch/2);
        translate([x_c - rib_thk/2, -plate_wid/2, plate_bot_z])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
