        translate([handle_start_x, -handle_width / 2, handle_top_z])
            cube([handle_end_x - handle_start_x, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere along the plane z = bowl_rim_z,
    // leaving only the lower half with the rim at z = 10
    translate([0, 0, bowl_rim_z - cut_overlap])
        cube([bowl_outer_radius * 2 + 2, 2 * bowl_outer_radius + 2, cut_overlap]);
}
