// Powder measuring scoop - hemispherical bowl with flat handle
// Print orientation: bowl opening upward, bottom touching bed at z = 0

$fn = 96;

// ---------- Bowl ----------
bowl_outer_r = 10;                         // outer radius of bowl sphere
bowl_wall    = 2;                          // wall thickness
bowl_inner_r = bowl_outer_r - bowl_wall;   // inner (cavity) radius = 8
bowl_cz      = 10;                         // sphere centre height (rim at z = 10)

// ---------- Handle ----------
handle_x0    = 8;     // handle start (x)
handle_x1    = 110;   // handle end (x)
handle_w     = 8;     // handle width (Y)
handle_t     = 3;     // handle thickness (Z)
handle_top_z = bowl_cz;                    // top face flush with rim (z = 10)

// ---------- Helpers ----------
eps = 0.5;            // overlap for clean boolean cuts

module bowl_solid() {
    // Lower half of the outer sphere (solid)
    intersection() {
        translate([0, 0, bowl_cz]) sphere(r = bowl_outer_r);
        translate([-bowl_outer_r - eps, -bowl_outer_r - eps, -eps])
            cube([2 * (bowl_outer_r + eps), 2 * (bowl_outer_r + eps), bowl_cz + eps]);
    }
}

module handle() {
    translate([handle_x0, -handle_w / 2, handle_top_z - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

difference() {
    union() {
        bowl_solid();
        handle();
    }
    // Hollow cavity (extends above rim into open air, so the bowl opens upward)
    translate([0, 0, bowl_cz]) sphere(r = bowl_inner_r);
}
