```openscad
// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len      = 60;    // plate length along X
plate_wid      = 25;    // plate width along Y
plate_thk      = 3;     // plate thickness along Z

knuckle_d      = 6;     // knuckle cylinder diameter
knuckle_h      = 3;     // knuckle height above plate top
knuckle_pitch  = 12;    // centre-to-centre spacing along X
knuckle_count  = 5;     // number of segments (1st, 3rd, 5th have knuckles)

pin_d          = 2;     // pin hole diameter
eps            = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Derived ----------
knuckle_x = [for (i = [0 : knuckle_count - 1])
              (i + 1) * knuckle_pitch / 2];  // -24, -12, 0, 12, 24
knuckle_active = [for (x = knuckle_x) abs(x) > knuckle_pitch / 4];  // 1,0,1,0,1

// ---------- Model ----------
union() {
    // Plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles (cylinder axis along X at y = 12.5, z = plate_thk + knuckle_h/2)
    for (x = knuckle_x)
        if (knuckle_active[x])
            translate([x, plate_wid / 2 - knuckle_d / 2, plate_thk])
                cylinder(d = knuckle_d, h = knuckle_h);

    // Pin holes through every knuckle
    for (x = knuckle_x)
        if (knuckle_active[x])
            translate([x, plate_wid / 2 - knuckle_d / 2, plate_thk])
                translate([0, 0, -eps])
                    cylinder(d = pin_d, h = knuckle_h + 2 * eps);
}
