    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1)/2) * knuckle_s;
        translate([x, plate_wid/2, knuckle_z - eps])
            cylinder(d = pin_d, h = knuckle_h + pin_overlap + 2*eps, $fn = 96);
