// Print orientation: flat on bed, z = 0 up to plate_t

// ---------- Parameters ----------
outer_r   = 30;   // distance from centre to outer points
inner_r   = 18;   // distance from centre to inner points
plate_t   = 4;    // plate thickness (Z)
hole_d    = 6;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces
$fn       = 96;   // curve resolution

// ---------- Model ----------
difference() {
    // Star outline: 8 outer points on +X start, 8 inner points between them
    polygon([for (i = [0:7])
        (i % 2 == 0) ? [outer_r, 0] : [inner_r, 0]]);  // base vectors
    rotate([0, 0, 45])
        polygon([for (i = [0:7])
        (i % 2 == 0) ? [outer_r, 0] : [inner_r, 0]]);  // next 8 points

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
```

```openscad
// Star-shaped indexing wheel (8-pointed), flat plate on the bed

// ---- Parameters ----
n_points   = 8;     // number of star points
r_outer    = 30;    // radius of outer (tip) points [mm]
r_inner    = 18;    // radius of inner (valley) points [mm]
thickness  = 4;     // plate thickness [mm]
hole_d     = 6;     // centre hole diameter [mm]
eps        = 0.5;   // cut overlap past faces [mm]
$fn        = 96;    // curve resolution

// ---- Star outline points ----
// Alternates outer/inner, first outer point on +X axis
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = i * 180 / n_points,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

// ---- Model ----
difference() {
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // centre through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = thickness + 2 * eps, $fn = 64);
}
