// Tapered riser block for beaker, with a square pocket in the top face
// Print orientation: base on the bed (z = 0), pocket opening facing up

// ---------- Dimensions (mm) ----------
bottom_size   = 80;   // bottom square side (X and Y)
top_size      = 40;   // top square side (X and Y)
height        = 30;   // block height (z = 0 to z = 30)
pocket_size   = 30;   // square pocket side (X and Y)
pocket_depth  = 8;    // pocket depth from the top face
eps           = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Main frustum body: bottom square up to a top square at the full height
    linear_extrude(height = height + eps)
        hull() {
            for (s = [bottom_size, top_size])
                translate([0, 0, eps * (s == bottom_size ? 1 : 0)])
                    cube([s, s, height + eps]);
        }

    // Square pocket cut into the top face, centred on the origin
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
