// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
total_len = grip_length + transition_len + gauge_length + transition_len + grip_length;   // 120 mm
min_w     = gauge_width;
max_w     = grip_width;

// ---------- Model ----------
difference() {
    // Solid body: union of grip, transition and gauge sections
    union() {
        for (s = [-1, 1]) {
            translate([s * (grip_length + transition_len / 2), -max_w / 2, 0])
                cube([grip_length, max_w, thickness]);                       // grip
            translate([s * (grip_length + transition_len / 2) - transition_len / 2,
                       -max_w / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len / 2, -max_w / 2], [-transition_len / 2, max_w / 2],
                              [transition_len / 2, max_w / 2], [transition_len / 2, -max_w / 2]]); // transition
        }
        translate([-transition_len - gauge_length / 2, -min_w / 2, 0])
            cube([gauge_length, min_w, thickness]);                         // gauge
    }

    // Cutters: overcut into end faces to avoid coplanar surfaces
    translate([-total_len / 2 - eps, -max_w / 2 - eps, -eps])
        cube([eps, max_w + 2 * eps, thickness + 2 * eps]);
    translate([total_len / 2 - eps, -max_w / 2 - eps, -eps])
        cube([eps, max_w + 2 * eps, thickness + 2 * eps]);
}
