// Flat tensile test specimen (dog bone)
// Lies flat on the bed (z = 0), centred on the origin in X and Y.

// ---------------- Parameters ----------------
thickness      = 4;    // specimen thickness (Z)
total_length   = 120;  // overall length (X)
gauge_width    = 8;    // width of narrow gauge section (Y)
gauge_length   = 30;   // length of gauge section (X)
grip_width     = 15;   // width of grip sections (Y)
grip_length    = 30;   // length of each grip section (X)
trans_length   = 15;   // length of each linear transition (X)

// Derived X positions (from centre outward)
x_gauge = gauge_length / 2;              // end of gauge section  (15)
x_trans = x_gauge + trans_length;        // end of transition     (30)
x_end   = x_trans + grip_length;         // end of grip / part    (60)

gw = gauge_width / 2;                    // half gauge width
pw = grip_width / 2;                     // half grip width

// Sanity check: computed length should equal total_length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

// ---------------- Outline (top view) ----------------
outline = [
    [-x_end,   -pw], [-x_trans, -pw], [-x_gauge, -gw],
    [ x_gauge, -gw], [ x_trans, -pw], [ x_end,   -pw],
    [ x_end,    pw], [ x_trans,  pw], [ x_gauge,  gw],
    [-x_gauge,  gw], [-x_trans,  pw], [-x_end,    pw]
];

// ---------------- Model ----------------
linear_extrude(height = thickness)
    polygon(outline);
```

```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to specimen thickness

// ---------------- Parameters ----------------
specimen_thickness   = 4;     // thickness (Z), mm
total_length         = 120;   // overall length along X, mm
gauge_width          = 8;     // gauge section width (Y), mm
gauge_length         = 30;    // gauge section length (X), mm
grip_width           = 15;    // grip section width (Y), mm
grip_length          = 30;    // grip section length (X), mm
transition_length    = 15;    // transition section length (X), mm
cut_extra            = 0.5;   // overshoot for clean boolean cuts, mm

$fn = 64;

// Derived: narrow end of transition (near gauge)
transition_narrow = gauge_width + (grip_width - gauge_width) * (transition_length / (transition_length * 2)); // 11 mm

// ---------------- Model ----------------
difference() {
    union() {
        // Left grip
        translate([-total_length / 2 + grip_length + transition_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Right grip
        translate([total_length / 2 - grip_length - transition_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Gauge section
        translate([-total_length / 2 + grip_length + transition_length + gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Left transition (width changes from grip_width to gauge_width)
        translate([-total_length / 2 + grip_length, -grip_width / 2, 0])
            linear_extrude(height = specimen_thickness)
                polygon([[-0, -grip_width / 2], [-transition_length, -grip_width / 2],
                         [-transition_length, transition_narrow - gauge_width / 2], [-0, transition_narrow - gauge_width / 2]]);

        // Right transition (width changes from gauge_width to grip_width)
        translate([total_length / 2 - grip_length - transition_length, -grip_width / 2, 0])
            linear_extrude(height = specimen_thickness)
                polygon([[0, -grip_width / 2], [transition_length, -grip_width / 2],
                         [transition_length, transition_narrow - gauge_width / 2], [0, transition_narrow - gauge_width / 2]]);
    }

    // Small cutouts along X near each end to avoid coplanar faces
    translate([-total_length / 2 - cut_extra, 0, -cut_extra])
        cube([cut_extra * 2, total_length, cut_extra * 2]);
}
