gauge_x0 = grip_x1 - gauge_length;                          // gauge start X (left)
gauge_x1 = grip_x0 + gauge_length;                          // gauge end X (right)

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = grip_x0 + transition_len * s;
            x1 = x0 + transition_len;
            w0 = grip_width;
            w1 = gauge_width;
            translate([x0, -w0/2, 0])
                linear_extrude([transition_len, thickness])
                    polygon([[-w0/2, w0/2], [w0/2, -w0/2], [w1/2, -w1/2], [-w1/2, w1/2]]);
        }
    }

