// Stiffened cover panel: flat plate with 4 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 120;   // plate length along X
plate_wid      = 60;    // plate width along Y
plate_thk      = 2;     // plate thickness (z = 0 to 2)

rib_count      = 4;     // number of ribs
rib_thk        = 3;     // rib thickness along X
rib_height     = 6;     // rib height above plate (z = 2 to 8)
rib_pitch      = 24;    // centre-to-centre spacing of ribs along X
rib_offset     = 24;    // centre of outer rib from nearest plate end

eps            = 0.5;   // cutter overshoot past faces
$fn            = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_top_z      = plate_thk + rib_height;   // top of ribs (z = 8)
plate_bot_z    = plate_thk;                // top of plate (z = 2)
outer_x        = [ -plate_len/2 + rib_offset,
                   plate_len/2 - rib_offset ];  // X of outer rib centres

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on their X positions, running full width along Y
    for (i = [0 : rib_count - 1]) {
        x_c = (i < 2) ? outer_x[i] : outer_x[i + 2];  // skip duplicates
        translate([x_c - rib_thk/2, -plate_wid/2, plate_bot_z])
            cube([rib_thk, plate_wid, rib_height]);
    }
}
