$fn            = 64;   // curve resolution (no curves here, set per rules)

// Derived: total length occupied by ribs + gaps = 5 * rib_pitch
total_rib_span = rib_count * rib_pitch + 2 * rib_offset;  // 4*16 + 2*16 = 96 mm
// Note: total_rib_span (96) > plate_len (80). The ribs will overhang the
// plate ends when cut through a plate of this length. If the intent was
// for every rib to sit fully on the plate, the pitch/offset would need to be
// reduced so that 2*offset + (rib_count-1)*pitch <= plate_len.
// The model follows the given numbers exactly.

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on their respective X positions
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch;  // rib centre X (0, 16, 32, 48)
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
