        translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
        // remove upper half
        translate([-(bowl_r_outer + eps), -(bowl_r_outer + eps), bowl_cz])
            cube([2 * (bowl_r_outer + eps), 2 * (bowl_r_outer + eps), bowl_r_outer + eps]);
    }
}

module handle() {
    translate([handle_x0, -handle_w / 2, handle_ztop - handle_t])
        cube([handle_x1 - handle_x0, handle_w, handle_t]);
}

difference() {
    union() {
        bowl();
        handle();
    }
    // keep bowl cavity clear of any handle material
    translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
}
