        for (i = [0 : knuckle_n - 1])
            translate([seg_c(i), knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h);
    }

    // Pin holes through every knuckle
    for (i = [0 : knuckle_n - 1])
        translate([seg_c(i), knuckle_y, knuckle_z])
