// Print orientation: flat on bed, hub pointing up (+Z)

// ---------- Parameters ----------
disc_d        = 30;    // disc diameter
disc_t        = 6;     // disc thickness
disc_x        = 5;     // disc centre X offset (y = 0)
hub_d         = 11;    // hub diameter
hub_h         = 5;     // hub height above disc
shaft_d       = 5;     // shaft hole diameter
eps           = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
union() {
    // Disc, centred at z = 0, shifted in X
    difference() {
        cylinder(d = disc_d, h = disc_t);
        translate([disc_x, 0, -eps])
            cylinder(d = shaft_d, h = disc_t + 2 * eps);   // shaft hole through disc
    }

    // Hub, centred on shaft axis, rising from z = disc_t to z = disc_t + hub_h
    difference() {
        translate([0, 0, disc_t])
            cylinder(d = hub_d, h = hub_h + 0.01);         // tiny overlap into disc for clean union
        translate([0, 0, -eps])
            cylinder(d = shaft_d, h = hub_h + 1 + 2 * eps); // shaft hole through hub
    }
}
```

```openscad
// Eccentric cam for shaker mechanism
// Print orientation: disc flat on bed (z = 0), hub upward. Shaft axis = Z axis.

$fn = 96;

// --- Dimensions (mm) ---
disc_d      = 30;   // cam disc diameter
disc_t      = 6;    // cam disc thickness
eccentric   = 5;    // offset of disc centre from shaft axis (along +X)
hub_d       = 11;   // hub outer diameter
hub_h       = 5;    // hub height above disc (z = 6 to 11)
shaft_d     = 5;    // shaft bore diameter
eps         = 0.5;  // overshoot for clean boolean cuts

difference() {
    union() {
        // Eccentric disc, centred at (eccentric, 0)
        translate([eccentric, 0, 0])
            cylinder(d = disc_d, h = disc_t);

        // Hub on shaft axis, slightly overlapping disc for a solid union
        translate([0, 0, disc_t - 0.01])
            cylinder(d = hub_d, h = hub_h + 0.01);
    }

    // Shaft bore through hub and disc on Z axis
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_t + hub_h + 2 * eps);
}
