// Star-shaped indexing wheel
// Print orientation: flat on the bed, building up in +Z

// ---------- Parameters ----------
n_points     = 6;     // number of star points
r_outer      = 40;    // radius to outer (tip) points [mm]
r_inner      = 20;    // radius to inner (valley) points [mm]
thickness    = 5;     // plate thickness [mm]
hole_d       = 8;     // centre hole diameter [mm]
cut_extra    = 0.5;   // extension of cutting shapes past faces [mm]
$fn          = 96;    // resolution for curved shapes

// ---------- Derived ----------
step = 360 / n_points;  // angle between successive outer points

// Star outline: alternate outer and inner vertices,
// first outer point on +X axis, inner points halfway between.
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (a = i * step / 2,
             r = (i % 2 == 0) ? r_outer : r_inner)
        [r * cos(a), r * sin(a)]
];

// ---------- Model ----------
difference() {
    // Star plate
    linear_extrude(height = thickness)
        polygon(points = star_pts);

    // Centre hole, extends past top and bottom faces
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra, $fn = 96);
}
