// Star-shaped indexing wheel - flat plate with central hole
// Print orientation: flat on bed, z = 0 up to plate_t

// ---------- Parameters ----------
outer_r   = 30;   // outer point distance from centre
inner_r   = 18;   // inner point distance from centre
points    = 8;    // number of points (star density)
plate_t   = 3;    // plate thickness (Z)
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

$fn = 96;

