difference() {
    // Star outline: outer point on +X axis, then alternating
    polygon([for (i = [0 : points - 1])
        r = (i % 2 == 0) ? outer_r : inner_r;
        [r * cos(i * 360 / points), r * sin(i * 360 / points)]]);

    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}
