// Solid square frustum with a square pocket in the top face.
// Print orientation: wide base on the bed (z = 0), builds upward.

// ---------- Dimensions (mm) ----------
base_size     = 100;   // bottom square side length (at z = 0)
top_size      = 80;    // top square side length (at z = height)
height        = 20;    // overall block height
pocket_size   = 72;    // square pocket side length in the top face
pocket_depth  = 8;     // pocket depth below the top face
overcut       = 0.5;   // extra length for cutting shapes past faces

// ---------- Derived ----------
scale_factor  = top_size / base_size;  // linear_extrude top scale

// ---------- Model ----------
difference() {
    // Solid square frustum, centred on origin, edges parallel to X/Y
    linear_extrude(height = height, scale = scale_factor)
        square([base_size, base_size], center = true);

    // Centred square pocket cut into the top face
    translate([0, 0, height - pocket_depth])
        linear_extrude(height = pocket_depth + overcut)
            square([pocket_size, pocket_size], center = true);
}
