// Cabinet door pull handle
// Print orientation: posts stand on the bed (z = 0), bar rests on top of them.

// ---------------- Parameters ----------------
post_d        = 12;    // post diameter (mm)
post_h        = 25;    // post height, z = 0 to 25 (mm)
post_x        = 32;    // post axis X position, +/- (mm)
post_y        = 0;     // post axis Y position (mm)

bar_len       = 76;    // bar length along X (mm)
bar_wid       = 12;    // bar width along Y (mm)
bar_thk       = 8;     // bar thickness along Z (mm)
bar_z0        = post_h + bar_thk; // bottom of bar, z = 33 (mm)
bar_z1        = bar_z0 + bar_thk; // top of bar, z = 41 (mm)

screw_d       = 4.5;   // screw hole diameter (mm)
screw_depth   = 12;    // screw hole depth from bottom face of post (mm)

eps           = 0.5;   // overshoot for clean boolean cuts (mm)
$fn           = 96;    // curve resolution

// ---------------- Model ----------------
union() {
    // Posts
    for (sx = [-1, 1]) {
        translate([sx * post_x, post_y, 0])
            cylinder(d = post_d, h = post_h);
    }

    // Bar
    translate([-bar_len / 2, -bar_wid / 2, bar_z0])
        cube([bar_len, bar_wid, bar_thk]);

    // Screw holes in posts, going up the axis from the bottom face
    for (sx = [-1, 1]) {
        translate([sx * post_x, post_y, 0])
            translate([0, 0, -eps])
                cylinder(d = screw_d, h = screw_depth + 2 * eps);
    }
}
