```openscad
// Cabinet door pull handle
// Print orientation: posts standing on the bed (z = 0), bar on top.

$fn = 96;

// --- Posts ---
post_d       = 12;    // post diameter
post_h       = 25;    // post height (z = 0 to 25)
post_spacing = 64;    // centre-to-centre distance (axes at x = -32 and x = 32)

// --- Bar ---
bar_len   = 76;       // bar length (X)
bar_w     = 12;       // bar width (Y)
bar_t     = 8;        // bar thickness (Z, z = 25 to 33)

// --- Screw holes ---
hole_d     = 4.5;     // screw hole diameter
hole_depth = 12;      // depth from bottom face of post

// --- Misc ---
eps     = 0.01;       // small overlap for unions
overcut = 0.5;        // extension of cutting tools past faces

module handle_body() {
    union() {
        // Posts (extended slightly into the bar so they fuse)
        for (sx = [-1, 1])
            translate([sx * post_spacing / 2, 0, 0])
                cylinder(d = post_d, h = post_h + eps);

        // Bar on top of posts
        translate([-bar_len / 2, -bar_w / 2, post_h])
            cube([bar_len, bar_w, bar_t]);
    }
}

difference() {
    handle_body();

    // Screw holes up each post axis from the bottom face
    for (sx = [-1, 1])
        translate([sx * post_spacing / 2, 0, -overcut])
            cylinder(d = hole_d, h = hole_depth + overcut);
}
