```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 10;    // transition section length (X)
total_length   = 110;   // overall specimen length (X)

eps            = 0.5;   // cutter overshoot past faces
$fn            = 96;    // curve resolution

// ---------- Derived ----------
grip_x0        = -total_length/2 + grip_length;   // left grip start X
gauge_x0       = grip_x0 + grip_length;           // gauge start X
trans_x0       = gauge_x0 + transition_len;       // transition start X
trans_x1       = trans_x0 + transition_len;       // transition end X
grip_x1        = trans_x1 + transition_len;       // right grip start X
check          = grip_x1 + grip_length;           // should equal +total_length/2

// ---------- Model ----------
difference() {
    // Solid body
    translate([-total_length/2, -thickness/2, 0])
        linear_extrude(thickness)
            polygon([[-total_length/2, -grip_width/2], [-total_length/2, grip_width/2],
                     [check, grip_width/2], [check, -grip_width/2]]);

    // Cutters for grip and gauge regions (extends past end faces)
    union() {
        // Left grip
        translate([grip_x0 - eps, -grip_width/2 - eps, -eps])
            linear_extrude(thickness + 2*eps)
                circle(d = grip_width, $fn = 96);
        // Right grip
        translate([grip_x1, -grip_width/2 - eps, -eps])
            linear_extrude(thickness + 2*eps)
                circle(d = grip_width, $fn = 96);
        // Gauge
        translate([gauge_x0 - eps, -gauge_width/2 - eps, -eps])
            linear_extrude(thickness + 2*eps)
                circle(d = gauge_width, $fn = 96);
    }
}
