gauge_x0 = grip_x0 + grip_length + transition_length; // gauge start X
right_x0 = gauge_x0 + gauge_length + transition_length; // right grip start X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Right grip
        translate([right_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Left transition (width: grip -> gauge)
        translate([grip_x0 + grip_length, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[(0, -grip_width/2), (0, grip_width/2),
                          (transition_length, -gauge_width/2),
                          (transition_length, gauge_width/2)]]);
        // Right transition (width: gauge -> grip)
        translate([right_x0 - transition_length, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[(0, -gauge_width/2), (0, gauge_width/2),
                          (transition_length, -grip_width/2),
                          (transition_length, grip_width/2)]]);
    }
    // End cutters, extended past faces
    translate([-total_length/2 - eps, -eps, -eps])
        cube([total_length, thickness, thickness + 2*eps]);
