// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 upward

// ---------------- Parameters ----------------
specimen_thickness   = 3;     // thickness along Z (mm)
total_length         = 130;   // overall length along X (mm)
gauge_width          = 8;     // gauge section width (Y) (mm)
gauge_length         = 50;    // gauge section length (X) (mm)
grip_width           = 15;    // grip section width (Y) (mm)
grip_length          = 25;    // grip section length (X) (mm)
transition_length    = 15;    // transition section length (X) (mm)
cut_extra            = 0.5;   // overshoot for clean boolean cuts (mm)

// Derived
grip_start_x         = -total_length/2 + grip_length;  // -52.5
gauge_start_x        = grip_start_x + transition_length; // -37.5
gauge_end_x          = gauge_start_x + gauge_length;    // 12.5
right_gauge_start_x   = -gauge_end_x;                   // -12.5 (symmetry)
right_gauge_end_x     = right_gauge_start_x + gauge_length; // 37.5
right_transition_end_x = right_gauge_end_x + transition_length; // 52.5
right_grip_end_x      = right_transition_end_x + grip_length; // 102.5

// ---------------- Model ----------------
difference() {
    // Solid block
    translate([-total_length/2, -specimen_thickness/2, 0])
        cube([total_length, specimen_thickness, 100]); // Y large, trimmed later

    // Cut along X, through full Y, at each feature boundary
    // (uses a thin wall so the cut passes through at z = 0)
    for (x = [grip_start_x - cut_extra, gauge_start_x - cut_extra,
              gauge_end_x + cut_extra, right_gauge_start_x - cut_extra,
              right_gauge_end_x + cut_extra, right_grip_end_x - cut_extra])
        translate([x, -specimen_thickness/2 - cut_extra, 0])
            cube([cut_extra + cut_extra, specimen_thickness + 2*cut_extra, 100]);
}
