// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
grip_x0 = -total_length/2 + grip_length;      // left grip start X
grip_x1 = total_length/2 - grip_length;       // right grip start X
trans_x0 = grip_x1 - transition_len;           // right transition start X
trans_x1 = trans_x0 + transition_len;          // right transition end X
trans_w0 = grip_width;                        // transition width at grip end
trans_w1 = gauge_width;                       // transition width at gauge end

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([-gauge_length/2, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Right transition (width changes linearly)
        translate([trans_x0, -trans_w0/2, 0])
            linear_extrude(height = thickness)
                polygon([[-transition_len/2, -trans_w0/2], [-transition_len/2, trans_w0/2],
                         [transition_len/2, trans_w1/2], [transition_len/2, -trans_w1/2]]);
    }
    // Cut along X to remove coplanar faces between parts
    translate([grip_x1 - eps, -grip_width/2 - eps, -eps])
        cube([transition_len + 2*eps, grip_width + 2*eps, thickness + 2*eps]);
    translate([trans_x1 - eps, -gauge_width/2 - eps, -eps])
        cube([transition_len + 2*eps, gauge_width + 2*eps, thickness + 2*eps]);
