                    polygon([
                        [0, -grip_width / 2], [grip_length, -grip_width / 2],
                        [grip_length, grip_width / 2], [0, grip_width / 2]
                    ]);
        }
        translate([-transition_length, 0, 0])
            linear_extrude(specimen_thickness)
                polygon([
                    [0, -transition_start_w / 2], [transition_length, -transition_end_w / 2],
                    [transition_length, transition_end_w / 2], [0, transition_start_w / 2]
                ]);
        translate([grip_length + transition_length, 0, 0])
            linear_extrude(specimen_thickness)
                polygon([
                    [0, -transition_start_w / 2], [transition_length, -transition_end_w / 2],
                    [transition_length, transition_end_w / 2], [0, transition_start_w / 2]
                ]);
        translate([(grip_length + transition_length) / 2 - gauge_length / 2, 0, 0])
            linear_extrude(specimen_thickness)
                rectangle([gauge_length, gauge_width]);
    }

    // End cutters, flush with the outermost grip faces
    translate([-total_length / 2 - cut_extra, 0, 0])
        linear_extrude(cut_extra)
            rectangle([cut_extra * 2, grip_width]);
    translate([total_length / 2 - cut_extra, 0, 0])
        linear_extrude(cut_extra)
            rectangle([cut_extra * 2, grip_width]);
}

// ---------------- QA ----------------
echo("Specimen thickness: " + specimen_thickness + " mm");
echo("Gauge area: " + area_gauge + " mm^2");
echo("Total length: " + total_length + " mm");
