// Flat tensile test specimen (dog bone) for printed plastics
// Lies flat on the bed, symmetric about the origin, long axis along X

// ---------------- Dimensions (mm) ----------------
thickness      = 3;    // specimen thickness (Z)
total_length   = 130;  // overall length (X)

gauge_length   = 30;   // length of the narrow gauge section (X)
gauge_width    = 10;   // width of the gauge section (Y)

trans_length   = 15;   // length of each linear transition (X)

grip_length    = 35;   // length of each grip section (X)
grip_width     = 20;   // width of each grip section (Y)

// Derived X stations (half-lengths from the origin)
x_gauge = gauge_length / 2;                 // 15  - end of gauge
x_trans = x_gauge + trans_length;           // 30  - end of transition
x_end   = x_trans + grip_length;            // 65  - end of grip
// Sanity check: x_end * 2 should equal total_length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not sum to total_length");

hg = gauge_width / 2;   // half gauge width
hw = grip_width / 2;    // half grip width

// ---------------- Outline (top view) ----------------
// Counter-clockwise polygon of the dog bone profile
outline = [
    [-x_end,   -hw],
    [-x_trans, -hw],
    [-x_gauge, -hg],
    [ x_gauge, -hg],
    [ x_trans, -hw],
    [ x_end,   -hw],
    [ x_end,    hw],
    [ x_trans,  hw],
    [ x_gauge,  hg],
    [-x_gauge,  hg],
    [-x_trans,  hw],
    [-x_end,    hw]
];

// ---------------- Model ----------------
linear_extrude(height = thickness)
    polygon(points = outline);
