// T-shaped extrusion nut / spacer - a T cross-section (flange + neck) with a central screw hole,
// sliding in an aluminium extrusion slot along X. NOVEL general part.
//

flange_w   = 14;   // flange width (Y)
flange_t   = 2.5;  // flange thickness (Z)
neck_w     = 6;    // neck width (Y)
neck_h     = 5.5;  // neck height above flange top (Z)
length     = 20;   // part length along X
screw_d    = 3.4;  // central screw hole diameter
eps        = 0.5;  // cutter overshoot

$fn = 64;

total_h = flange_t + neck_h;

difference() {
    union() {
        // flange
        translate([-length/2, -flange_w/2, 0]) cube([length, flange_w, flange_t]);
        // neck
        translate([-length/2, -neck_w/2, flange_t]) cube([length, neck_w, neck_h]);
    }
    // screw hole
    translate([0, 0, -eps]) cylinder(d = screw_d, h = total_h + 2*eps);
}
