// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 15;   // outer radius of the spherical bowl
bowl_wall_thickness = 1.5;  // thickness of the bowl wall
bowl_centre         = 15;   // Z position of the sphere centre (0, 0, 15)
handle_width        = 12;   // handle width (Y)
handle_thickness    = 4;    // handle thickness (Z)
handle_x_start      = 13.5; // handle start position (X)
handle_x_end        = 75;   // handle end position (X)
cut_extra           = 0.5;  // overshoot for clean boolean cuts

$fn = 96;

// ---------------- Derived ----------------
rim_z = bowl_centre + bowl_outer_radius;   // rim height (z = 15)
bowl_inner_r = bowl_outer_radius - bowl_wall_thickness;  // 13.5 mm

// ---------------- Model ----------------
difference() {
    union() {
        // Spherical bowl (full sphere)
        translate([0, 0, bowl_centre])
            sphere(r = bowl_outer_radius);

        // Flat handle, top face flush with rim (z = 11 to 15)
        translate([handle_x_start, -handle_width / 2,
                   bowl_centre - handle_thickness])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Lower half of the bowl: cut with a horizontal plane at z = 0
    translate([0, 0, -cut_extra])
        cube([bowl_outer_radius * 2 + 2 * cut_extra,
              bowl_outer_radius * 2 + 2 * cut_extra,
              bowl_centre + cut_extra]);
}
