```openscad
// Powder measuring scoop: hemispherical bowl + flat handle
// Print orientation: bowl bottom on bed (z = 0), opening upward

$fn = 96;

// ---- Bowl ----
bowl_outer_r = 15;     // outer radius of bowl
bowl_wall    = 1.5;    // bowl wall thickness
bowl_inner_r = bowl_outer_r - bowl_wall; // inner radius (13.5)
bowl_cz      = 15;     // sphere centre height (rim height)

// ---- Handle ----
handle_w     = 12;     // handle width (Y)
handle_t     = 4;      // handle thickness (Z)
handle_x0    = 13.5;   // handle start (X)
handle_x1    = 75;     // handle end (X)
handle_top   = bowl_cz;              // top face flush with rim
handle_z0    = handle_top - handle_t; // bottom face (z = 11)

eps = 0.5;             // cutter overlap

difference() {
    union() {
        // solid lower half of outer sphere
        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_outer_r);
            translate([-bowl_outer_r - eps, -bowl_outer_r - eps, -eps])
                cube([2 * (bowl_outer_r + eps),
                      2 * (bowl_outer_r + eps),
                      bowl_cz + eps]);
        }
        // handle
        translate([handle_x0, -handle_w / 2, handle_z0])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }
    // hollow the bowl (also trims handle out of the cavity);
    // sphere extends above the rim so no coplanar faces
    translate([0, 0, bowl_cz]) sphere(r = bowl_inner_r);
}
