// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles per leaf
knuckle_y   = 15;   // knuckle axis Y position
knuckle_z   = 4;    // knuckle axis height above bed
knuckle_pitch = (plate_len - 2 * 7.5) / (knuckle_n - 1); // 15 mm centre-to-centre

// ---- Pin ----
pin_d       = 3;    // pin diameter
pin_overcut = 0.5;  // extension of cutters past knuckle faces

// ---- Derived ----
knuckle_r = knuckle_d / 2;
first_x   = -plate_len / 2 + knuckle_pitch / 2;   // -15 mm
last_x    = plate_len / 2 - knuckle_pitch / 2;     // 15 mm

difference() {
    // Plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckle cylinders with pin holes
    for (i = [0 : knuckle_n - 1]) {
        translate([first_x + i * knuckle_pitch, knuckle_y, knuckle_z])
            difference() {
                cylinder(d = knuckle_d, h = plate_thk + 2 * pin_overcut);
                translate([0, 0, -pin_overcut])
                    cylinder(d = pin_d, h = plate_thk + 2 * pin_overcut + 2 * pin_d);
            }
    }
}
