// Pin hinge leaf - one leaf with two outer knuckles
$fn = 64;

// Plate
plate_len   = 45;    // X length of plate
plate_wid   = 30;    // Y width of plate
plate_thk   = 2.5;   // plate thickness (Z)

// Knuckles
n_segments  = 3;                      // number of equal segments along the edge
seg_len     = plate_len / n_segments; // 15 mm per segment
knuckle_d   = 8;     // knuckle outer diameter
axis_y      = 15;    // hinge axis Y position (+Y edge)
axis_z      = 4;     // hinge axis Z height

// Pin hole
pin_d       = 3;     // pin hole diameter
eps         = 0.5;   // cut overshoot

difference() {
    union() {
        // Flat plate centred on origin
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments (even indices)
        for (i = [0 : n_segments - 1])
            if (i % 2 == 0)
                translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
                    rotate([0, 90, 0])
                        cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis through all knuckles
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
