// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len      = 60;    // plate length along X (mm)
plate_wid      = 25;    // plate width along Y (mm)
plate_thk      = 3;     // plate thickness along Z (mm)

knuckle_d      = 7;     // knuckle cylinder diameter (mm)
knuckle_z      = 3.5;   // knuckle axis height above bed (mm)
knuckle_count  = 5;     // number of knuckle segments
knuckle_pitch  = 12;    // centre-to-centre spacing along X (mm)
knuckle_hole_d = 3;     // pin hole diameter (mm)

eps            = 0.5;   // cutter overshoot past faces (mm)
$fn            = 96;    // curve resolution

// ---------- Derived ----------
knuckle_x = [i * knuckle_pitch - (knuckle_count - 1) * knuckle_pitch / 2
             for i in [0 : knuckle_count - 1]];  // segment centres
active    = [i for i in [0 : knuckle_count - 1] if (i + 1) % 2 == 1];  // 1st,3rd,5th

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles with pin holes
    for (x in knuckle_x)
        if (x in active)
            translate([x, plate_wid / 2, knuckle_z])
                difference() {
                    cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
                    translate([0, 0, -eps])
                        cylinder(d = knuckle_hole_d, h = plate_thk + 2 * eps);
                }
}
