overlap     = 0.01; // small overlap to fuse hub into disc

difference() {
    union() {
        // Eccentric disc, centred at (eccentric, 0)
        translate([eccentric, 0, 0])
            cylinder(d = disc_d, h = disc_t);

        // Hub on shaft axis, sitting on top of disc
        translate([0, 0, disc_t - overlap])
            cylinder(d = hub_d, h = hub_h + overlap);
    }

    // Shaft bore through hub and disc along Z axis
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = disc_t + hub_h + 2 * eps);
}
