```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 120;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
grip_x = grip_length * 2 + gauge_length;  // distance between gauge end and grip start (each side)
x0    = -total_length / 2;              // left end X position

// Width of a point on the outline, given its X offset from the left end
function width(x) =
    if (x < grip_x)
        grip_width
    else if (x < grip_x + transition_len)
        grip_width - (grip_width - gauge_width) * (x - grip_x) / transition_len
    else if (x < grip_x + 2 * transition_len + gauge_length)
        gauge_width
    else if (x < grip_x + 2 * transition_len + gauge_length + transition_len)
        gauge_width + (grip_width - gauge_width) * (x - (grip_x + 2 * transition_len + gauge_length)) / transition_len
    else
        grip_width;

difference() {
    // Solid body
    translate([x0, -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon([for (x = [0 : total_length]) [x, width(x) / 2]]);

    // Through-cut along X, centred on the gauge section
    translate([x0 + grip_x / 2 + eps, -gauge_width / 2, -eps])
        cube([gauge_length + 2 * eps, gauge_width + 2 * eps, thickness + 2 * eps]);
}
```

