x_trans = x_gauge + trans_length;           // end of transition (35)
x_end   = x_trans + grip_length;            // end of grip (60)
hg      = gauge_width / 2;                  // half gauge width
hw      = grip_width / 2;                   // half grip width

// Sanity check: segments must add up to the total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Segment lengths do not sum to total_length");

// ---------------- Outline (top view) ----------------
outline = [
    [-x_end,   -hw], [-x_trans, -hw], [-x_gauge, -hg],
    [ x_gauge, -hg], [ x_trans, -hw], [ x_end,   -hw],
    [ x_end,    hw], [ x_trans,  hw], [ x_gauge,  hg],
    [-x_gauge,  hg], [-x_trans,  hw], [-x_end,    hw]
];

// ---------------- Part ----------------
linear_extrude(height = thickness)
    polygon(outline);
