            cube([grip_length, grip_width, thickness]);

        // Left transition (15 -> 8 mm width)
        translate([grip_x0 + grip_length, -transition_w1/2, 0])
            linear_extrude(thickness)
                polygon([[-transition_len/2, -transition_w1/2], [-transition_len/2, transition_w1/2],
