eps = 0.5;

difference() {
    // Main body: grip + transition + gauge + transition + grip
    union() {
        for (s = [-1, 1]) {
            translate([s * overlap / 2, 0, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, -grip_width / 2], [grip_length, -grip_width / 2],
                        [grip_length, grip_width / 2], [0, grip_width / 2]
                    ]);
        }
        translate([-overlap / 2, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -transition_len], [transition_len, -transition_len],
                    [transition_len, transition_len], [0, transition_len]
                ]);
        translate([overlap / 2 - gauge_length, 0, 0])
            linear_extrude(thickness)
                rectangle([gauge_length, gauge_width]);
    }

    // End cutters, extended past the faces
    translate([-total_length / 2 - eps, 0, -eps])
        cube([eps, total_length, 2 * eps]);
    translate([total_length / 2 - eps, 0, -eps])
        cube([eps, total_length, 2 * eps]);
