        // Left grip
        translate([grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([total_length - grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (width: grip_width -> gauge_width)
        translate([grip_x0 + transition_len, -grip_width / 2, 0])
            linear_extrude(height = thickness)
                polygon([[-transition_len, grip_width / 2],
                         [-transition_len, -grip_width / 2],
                         [gauge_x0, -gauge_width / 2],
                         [gauge_x0, gauge_width / 2]]);

        // Right transition (width: grip_width -> gauge_width)
        translate([total_length - grip_x0 - transition_len, -grip_width / 2, 0])
            linear_extrude(height = thickness)
                polygon([[transition_len, grip_width / 2],
                         [transition_len, -grip_width / 2],
                         [gauge_x0 + gauge_length, -gauge_width / 2],
                         [gauge_x0 + gauge_length, gauge_width / 2]]);
