// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to wheel_thickness

// ---------- Parameters ----------
outer_d      = 80;    // outer rim diameter
rim_width    = 6;     // rim width (radial)
hub_d        = 20;    // hub diameter
axle_d       = 8;     // centre axle hole diameter
spoke_d      = 5;     // spoke width
spoke_count  = 4;     // number of spokes
spoke_start  = 0;     // angle of first spoke (deg, 0 = +X axis)
wheel_thickness = 5;  // part thickness (Z)
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Derived ----------
rim_i_d = outer_d - 2 * rim_width;   // inner diameter of rim ring
spoke_h = wheel_thickness;           // spokes run full height

// ---------- Model ----------
union() {
    // Outer rim ring
    difference() {
        cylinder(d = outer_d, h = rim_width);
        translate([0, 0, -eps])
            cylinder(d = rim_i_d, h = rim_width + 2 * eps);
    }

    // Hub with axle hole
    difference() {
        cylinder(d = hub_d, h = wheel_thickness);
        translate([0, 0, -eps])
            cylinder(d = axle_d, h = wheel_thickness + 2 * eps);
    }

    // Radial spokes
    for (i = [0 : spoke_count - 1]) {
        a = spoke_start + i * 360 / spoke_count;
        translate([0, 0, -eps])
            linear_extrude(height = spoke_h + 2 * eps)
                polygon([[-hub_d / 2, 0], [hub_d / 2, 0],
                          [hub_d / 2, spoke_d], [-hub_d / 2, spoke_d]]);
    }
}
