// Powder measuring scoop - hemispherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), opening upward

$fn = 96;

// ---------- Bowl ----------
bowl_r_outer = 15;      // outer radius of bowl sphere
bowl_wall    = 1.5;     // wall thickness
bowl_r_inner = bowl_r_outer - bowl_wall; // inner radius (13.5)
bowl_cz      = 15;      // sphere centre height (rim height)

// ---------- Handle ----------
handle_x0    = 13.5;    // handle start (x)
handle_x1    = 75;      // handle end (x)
handle_w     = 10;      // handle width (Y)
handle_t     = 4;       // handle thickness (Z)
handle_top   = bowl_cz; // top face flush with rim (z = 15)

eps = 0.5;              // overlap for clean boolean cuts

difference() {
    union() {
        // Lower half of outer sphere (rim at z = 15)
        intersection() {
            translate([0, 0, bowl_cz]) sphere(r = bowl_r_outer);
            translate([-bowl_r_outer - 1, -bowl_r_outer - 1, -1])
                cube([2 * bowl_r_outer + 2, 2 * bowl_r_outer + 2, bowl_cz + 1]);
        }

        // Flat handle along +X, z = 11..15
        translate([handle_x0, -handle_w / 2, handle_top - handle_t])
            cube([handle_x1 - handle_x0, handle_w, handle_t]);
    }

    // Hollow bowl cavity (extends above rim to open the top cleanly)
    translate([0, 0, bowl_cz]) sphere(r = bowl_r_inner);
    translate([0, 0, bowl_cz])
        cylinder(r = bowl_r_inner, h = handle_t + eps);
}
