// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height (Z)
knuckle_y   = 10;   // knuckle axis Y position
knuckle_n   = 3;    // number of knuckle segments
knuckle_dx  = plate_len / knuckle_n; // segment length (15 mm)

// ---- Pin ----
pin_d       = 3;    // pin diameter
pin_overlap = 1;    // extra length of pin through knuckles

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces

difference() {
    union() {
        // Plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st and 3rd segments
        for (i = [0, knuckle_n - 1]) {
            translate([-knuckle_dx * i + knuckle_dx/2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
        }
    }

    // Pin holes through knuckles
    for (i = [0, knuckle_n - 1]) {
        translate([-knuckle_dx * i + knuckle_dx/2, knuckle_y, knuckle_z])
            translate([0, 0, -pin_overlap])
                cylinder(d = pin_d, h = plate_thk + 2 * pin_overlap);
    }
}
