knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height (above top face)
knuckle_n   = 3;    // number of knuckles
knuckle_pitch = (plate_len - 2 * knuckle_d) / (knuckle_n - 1); // 15 mm centre-to-centre

// ---- Pin hole ----
