            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge, axis along X at y = 10
        for (i = [0 : knuckle_n - 1]) {
            x = i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2;
            translate([x, plate_wid/2 - knuckle_d/2, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
        }
    }

    // Pin hole through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
        x = i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2;
        translate([x, plate_wid/2 - knuckle_d/2, knuckle_z])
            translate([-eps, 0, -eps])
                cylinder(d = pin_d, h = plate_thk + 2 * eps + 2);
    }
