// Print orientation: plate flat on the bed (z = 0), knuckles build upward

// ---------------- Parameters ----------------
plate_len   = 45;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 3;     // plate thickness (Z)

n_segments  = 3;                       // number of equal segments along the edge
seg_len     = plate_len / n_segments;  // segment length (15 mm)
knuckle_segs = [0, 2];                 // segments carrying knuckles (1st and 3rd)

knuckle_d   = 6;     // knuckle diameter
axis_y      = 15;    // hinge axis Y position (+Y edge)
axis_z      = 3;     // hinge axis Z position

pin_d       = 2.5;   // pin hole diameter
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;            // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the selected segments
        for (i = knuckle_segs)
            translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
    }

    // Pin hole along the hinge axis, through every knuckle
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
