```openscad
// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

knuckle_d   = 8;     // knuckle (cylinder) diameter
knuckle_z   = 4;     // knuckle axis height above bed
knuckle_n   = 5;     // number of segments along plate length
knuckle_pitch = plate_len / knuckle_n; // 10 mm centre-to-centre

pin_d       = 3;     // pin hole diameter
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on +Y edge, 1st/3rd/5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) { // 1st, 3rd, 5th segments (0-indexed)
                translate([(i - 1) * knuckle_pitch/2 + knuckle_pitch/2,
                           plate_wid/2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2*eps, $fn = 96);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([(i - 1) * knuckle_pitch/2 + knuckle_pitch/2,
                       plate_wid/2,
                       knuckle_z])
                translate([-eps, 0, -eps])
                    cylinder(d = pin_d, h = plate_thk + 2*eps, $fn = 64);
        }
    }
}
