// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 60;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;     // knuckle diameter
knuckle_n   = 5;     // number of knuckle segments
knuckle_pitch = (plate_len - 2) / knuckle_n; // 12 mm centre-to-centre
knuckle_z   = 3;     // knuckle axis height above bed
knuckle_y   = plate_wid / 2; // axis Y position (= 12.5)

// ---- Pin ----
pin_d       = 2;     // pin diameter
pin_overlap = 1;     // extra length of pin past each knuckle end

// ---- Cutting clearance ----
eps         = 0.5;   // extension of cutters past faces

// Derived
knuckle_r = knuckle_d / 2;

difference() {
    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders
        for (i = [0 : knuckle_n - 1]) {
            x = i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2;
            translate([x, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
        }
    }

    // Pin bore through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x = i * knuckle_pitch - (knuckle_n - 1) * knuckle_pitch / 2;
        translate([x, knuckle_y, knuckle_z])
