$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // overlap for clean boolean cuts
grip_x = grip_length * 2 + gauge_length + transition_len * 2; // 110 mm
centre = (total_length - grip_x) / 2; // -15 mm offset of gauge centre

difference() {
    // Main body: grip + gauge + transitions, centred on origin in X/Y
    translate([-total_length / 2, -grip_width / 2, 0])
        linear_extrude(thickness)
            polygon([[-total_length / 2, -grip_width / 2], [-total_length / 2, grip_width / 2],
                     [total_length / 2, grip_width / 2], [total_length / 2, -grip_width / 2]]);

    // Central gauge section (undercut in Y)
    translate([centre - gauge_length / 2, -gauge_width / 2 - eps, 0])
        linear_extrude(thickness + 2 * eps)
            rectangle([gauge_length, gauge_width]);

    // End grip sections (undercut in X)
    for (s = [-1, 1])
        translate([s > 0 ? centre + gauge_length / 2 + transition_len / 2 :
                    -centre - gauge_length / 2 - transition_len / 2,
                   -grip_width / 2 - eps, 0])
            linear_extrude(thickness + 2 * eps)
                rectangle([grip_length, grip_width]);
}
