grip_x0 = -total_length/2 + grip_length;      // left grip start X
grip_x1 = total_length/2 - grip_length;       // right grip start X
trans_x0 = grip_x0 + grip_length;             // transition start X (left)
trans_x1 = grip_x1 - grip_length;             // transition end X (right)
gauge_x0 = trans_x0 + transition_len;         // gauge start X (left)
gauge_x1 = trans_x1 - transition_len;         // gauge end X (right)

// ---------- Model ----------
difference() {
    union() {
        // Grip sections
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transition sections (width changes linearly from grip to gauge)
        translate([trans_x0, -grip_width/2, 0])
            linear_extrude([transition_len, grip_width])
                cube([transition_len, grip_width, thickness]);
        translate([trans_x1, -grip_width/2, 0])
            linear_extrude([transition_len, grip_width])
                cube([transition_len, grip_width, thickness]);

