    translate([grip_x0 - 0.5, -grip_width/2 - 0.5, 0])
        cube([0.5, grip_width + 1, thickness + 0.5]);
    translate([grip_x1 - 0.5, -grip_width/2 - 0.5, 0])
        cube([0.5, grip_width + 1, thickness + 0.5]);
