        // End grips
        translate([-total_length / 2 + grip_x / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);
        translate([ total_length / 2 - grip_x / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Central gauge
        translate([centre, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1])
            translate([centre + s * (grip_x / 2 + gauge_length / 2 + transition_len / 2),
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-grip_width / 2, -transition_len / 2], [-grip_width / 2, transition_len / 2],
                              [gauge_width / 2, transition_len / 2], [gauge_width / 2, -transition_len / 2]]);
    }

    // Cut along X through the gauge section, stopping in the grip zones
    translate([centre - gauge_length / 2 - eps, -thickness / 2 - eps, 0])
        cube([gauge_length + 2 * eps, thickness + 2 * eps, total_length / 2 + eps]);
    translate([centre + gauge_length / 2 - eps, -thickness / 2 - eps, 0])
        cube([gauge_length + 2 * eps, thickness + 2 * eps, total_length / 2 + eps]);
