    [ hg, -gw2], [ ht, -pw2], [ hl, -pw2],
    [ hl,  pw2], [ ht,  pw2], [ hg,  gw2],
    [-hg,  gw2], [-ht,  pw2], [-hl,  pw2]
];

linear_extrude(height = thickness)
