// Cable bridge - a block with semicircular tunnels along Y at floor level
// Units: mm

// ---- Block ----
block_len   = 60;   // block length along X
block_wid   = 40;   // block width along Y
block_ht    = 12;   // block height along Z

// ---- Tunnels ----
tunnel_d    = 12;   // tunnel diameter (cylinder along Y)
tunnel_pitch = 16;  // centre-to-centre spacing along X
tunnel_n    = 3;    // number of tunnels
floor_z     = 0;    // floor level (tunnel axes lie here)

// ---- Misc ----
eps         = 0.5;  // cutter overshoot past faces
$fn         = 96;   // curve resolution

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels through along Y
    for (i = [0 : tunnel_n - 1]) {
        x_c = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x_c, 0, floor_z])
            rotate([0, 90, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
}
