// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 60;   // plate length along X
plate_wid   = 25;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter
knuckle_n   = 3;    // number of knuckles per leaf
knuckle_y   = plate_wid / 2; // knuckle axis Y position (12.5)
knuckle_z   = plate_thk + 2; // knuckle axis Z position (5)

// ---- Pin ----
pin_d       = 3;    // pin hole diameter
pin_overlap = 0.5;  // extra length of pin through knuckles for a solid union

// ---- Segments ----
seg_len     = plate_len / knuckle_n; // 20 mm per segment

// ---- Cutting clearance ----
eps         = 0.5;  // extension of cutters past faces

difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders (on 1st and 3rd segments)
        for (i = [0 : knuckle_n - 1]) {
            x_c = (i - (knuckle_n - 1) / 2) * seg_len;
            if (i % 2 == 0) // 1st and 3rd segments
                translate([x_c - seg_len / 2, knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2 * pin_overlap);
        }
    }

    // Pin holes through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x_c = (i - (knuckle_n - 1) / 2) * seg_len;
        if (i % 2 == 0)
            translate([x_c - seg_len / 2, knuckle_y, knuckle_z])
                cylinder(d = pin_d, h = plate_thk + 2 * pin_overlap + 2 * eps);
    }
}
