    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1) / 2) * knuckle_s;
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_thk + 2 * pin_overlap + 2 * eps);
    }
}
