```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // overlap for clean boolean cuts
grip_x = grip_length * 2 + gauge_length + transition_len * 2; // 120 mm
centre = (total_length - grip_x) / 2; // -10 mm offset of gauge centre

difference() {
    // Main body: grip + transition + gauge + transition + grip
    union() {
        for (s = [-1, 1]) {
            translate([s * grip_x / 2 - centre, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        for (s = [-1, 1]) {
            translate([s * (grip_length + transition_len) / 2 - centre,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-grip_width / 2, -transition_len / 2],
                              [-grip_width / 2, transition_len / 2],
                              [gauge_width / 2, transition_len / 2],
                              [gauge_width / 2, -transition_len / 2]]);
        }
        translate([-centre - gauge_width / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // End cutters, overcutting past the faces
    translate([-total_length / 2 - eps, -thickness / 2 - eps, -eps])
        cube([eps + total_length / 2 + gauge_width / 2 + transition_len / 2,
              thickness + 2 * eps, 2 * eps]);
    translate([ total_length / 2 - eps, -thickness / 2 - eps, -eps])
        cube([eps + total_length / 2 - gauge_width / 2 - transition_len / 2,
              thickness + 2 * eps, 2 * eps]);
}
