gauge_x1 = gauge_x0 + gauge_length;                         // gauge end X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Left transition (width: grip_width -> gauge_width)
        translate([gauge_x0 - transition_len, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[-transition_len, -grip_width/2], [-transition_len, grip_width/2],
                         [0, gauge_width/2], [0, -gauge_width/2]]);

        // Right transition (width: grip_width -> gauge_width)
        translate([gauge_x1, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[-transition_len, -grip_width/2], [-transition_len, grip_width/2],
                         [0, gauge_width/2], [0, -gauge_width/2]]);
    }

    // Small cutters to avoid coplanar faces
    translate([-total_length/2 - 1, -grip_width/2 - 1, -1])
        cube([grip_length + 2, grip_width + 2, thickness + 2]);

    translate([total_length/2 - grip_length, -grip_width/2 - 1, -1])
        cube([grip_length + 2, grip_width + 2, thickness + 2]);

    translate([gauge_x0 - 1, -gauge_width/2 - 1, -1])
        cube([gauge_length + 2, gauge_width + 2, thickness + 2]);

    translate([gauge_x0 - transition_len - 1, -grip_width/2 - 1, -1])
        cube([transition_len + 2, grip_width + 2, thickness + 2]);

    translate([gauge_x1, -grip_width/2 - 1, -1])
        cube([transition_len + 2, grip_width + 2, thickness + 2]);
}
