// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
grip_x0 = -grip_length - transition_len;   // left grip start X
grip_x1 = grip_length + transition_len;    // right grip end X
gauge_x0 = -gauge_length / 2;              // gauge centre start X
gauge_x1 = gauge_length / 2;               // gauge centre end X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([grip_x1 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            dx = s > 0 ? gauge_x0 - grip_x1 : grip_x1 - gauge_x0;
            translate([grip_x1 - dx * (transition_len / 2), -grip_width / 2, 0])
                linear_extrude([dx, thickness])
                    polygon([[-transition_len / 2, -grip_width / 2],
                              [-transition_len / 2, grip_width / 2],
                              [transition_len / 2, grip_width / 2 * (1 - transition_len / (2 * dx))],
                              [transition_len / 2, -grip_width / 2 * (1 - transition_len / (2 * dx))]]);
        }
    }

    // Cutters for clean overlaps (no coplanar faces)
    translate([grip_x1 - grip_length - transition_len - eps, -grip_width / 2 - eps, -eps])
        cube([grip_length + eps + transition_len + eps, grip_width + 2 * eps, thickness + 2 * eps]);

    translate([grip_x1 - grip_length - transition_len - eps, -grip_width / 2 - eps, -eps])
        cube([grip_length + eps + transition_len + eps, grip_width + 2 * eps, thickness + 2 * eps]);
}
