gauge_length   = 30;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge
total_length   = 130;   // overall specimen length along X

// Derived: start of first grip
grip_start_x = -total_length / 2 + grip_length;

// Check: gauge + 2*transition + 2*grip = 30 + 30 + 70 = 130 mm

difference() {
    union() {
        // Left grip
        translate([grip_start_x, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([grip_start_x + grip_length, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (linear width change, overextruded past faces)
        eps = 0.5;
        for (s = [-1, 1]) {
            x0 = grip_start_x + grip_length;              // gauge start
            x1 = x0 + transition_len;                      // transition end
            y0 = gauge_width / 2;
            y1 = grip_width / 2;
            translate([x0 - s * eps, -y1 / 2, 0])
                linear_extrude(thickness + 2 * eps)
                    polygon([[x0 - s * eps, -y1 / 2], [x1 + s * eps, -y1 / 2],
                              [x1 + s * eps, y1 / 2], [x0 - s * eps, y1 / 2]]);
        }
    }

    // Small cutters to avoid coplanar faces
    for (x = [grip_start_x + grip_length, total_length / 2 - grip_length]) {
        translate([x - 0.5, 0, -1])
            cube([1, thickness + 2, 0.01]);
    }
}
