// Stiffened cover panel: flat plate with 3 transverse ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 80;   // plate length along X
plate_wid      = 80;   // plate width along Y
plate_thk      = 2;    // plate thickness (z = 0 to 2)

rib_thk        = 2;    // rib thickness along X
rib_h          = 4;    // rib height above plate (z = 2 to 6)
rib_count      = 3;    // number of ribs
rib_pitch      = 20;   // centre-to-centre spacing of ribs
rib_offset     = 20;   // centre of outer rib from plate end

eps            = 0.5;  // overcut so cutters pass through faces
$fn            = 64;   // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_top_z      = plate_thk + rib_h;   // top of ribs (z = 6)
x0             = -plate_len / 2 + rib_offset;  // x of first rib centre
x_n             = x0 + (rib_count - 1) * rib_pitch;  // x of last rib centre

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, standing on the plate top face
    for (i = [0 : rib_count - 1]) {
        translate([x0 + i * rib_pitch - rib_thk / 2,
                   -plate_wid / 2,
                   rib_top_z - eps])
            cube([rib_thk, plate_wid, rib_h + 2 * eps]);
    }
}
