// Pin hinge - one leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 40;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter
knuckle_n   = 5;    // number of knuckle segments
knuckle_pitch = plate_len / knuckle_n;  // 8 mm centre-to-centre
knuckle_y   = plate_wid / 2;            // knuckle axis Y position (15)
knuckle_z   = plate_thk + 2;            // knuckle axis Z position (4.5)

// ---- Pin hole ----
pin_d       = 2.5;  // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension of cutters past faces

// Knuckle X positions, centred on the plate
knuckle_x = [
    for (i = [0 : knuckle_n - 1])
        (i - (knuckle_n - 1) / 2) * knuckle_pitch
];

difference() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles with pin holes; cylinder extends above the top face
    for (x = knuckle_x)
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = eps, $fn = 96);

    // Pin hole running along X through every knuckle
    translate([knuckle_x[0] - eps, knuckle_y, knuckle_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2 * eps, $fn = 96);
}
