```openscad
// Star-shaped indexing wheel - a flat 6-pointed star plate with a central through hole,
// printed lying flat on the bed. The outline alternates between outer points at 35 mm
// and inner points at 21 mm from the centre, evenly spaced in angle, with the first
// outer point on the +X axis.
//

// ---------- Parameters ----------
outer_r   = 35;   // distance of outer star points from the centre
inner_r   = 21;   // distance of inner star points (re-entrant corners) from the centre
thickness = 5;    // plate thickness (Z)
hole_d    = 8;    // diameter of the central through hole
eps       = 0.5;  // overcut so cutting shapes pass beyond the faces they cut

$fn = 96;

// ---------- Model ----------
difference() {
    // Solid disc that covers the entire star outline
    cylinder(h = thickness, r = outer_r);

    // Cut out the 6 wedge-shaped regions between the outer and inner points.
    // The vertices of each wedge lie on the same ray from the centre, so the cuts
    // meet cleanly at the star's corners.
    for (i = [0 : 5])
        rotate([0, 0, i * 60])
            translate([inner_r, 0, -eps])
                cube([outer_r - inner_r, 2 * eps, thickness]);

    // Central through hole
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = hole_d);
}
