        union() {
            for (s = [-1, 1]) {
                translate([s * (grip_length + transition_len), -grip_width / 2, 0])
                    cube([grip_length, grip_width, thickness]);
            }
            translate([-grip_length - transition_len, -gauge_width / 2, 0])
                cube([gauge_length, gauge_width, thickness]);
            for (s = [-1, 1]) {
                translate([s * (grip_length + transition_len), -grip_width / 2, 0])
                    cube([transition_len, grip_width, thickness]);
