        }
        // End cutters, extended past faces
        translate([-total_length / 2 - eps, -grip_width / 2 - eps, -eps])
            cube([eps, grip_width + 2 * eps, thickness + 2 * eps]);
        translate([total_length / 2 - eps, -grip_width / 2 - eps, -eps])
            cube([eps, grip_width + 2 * eps, thickness + 2 * eps]);
    }
}

specimen();
