                         [-transition_w1 / 2, transition_w2 / 2],
                         [transition_w2 / 2, transition_w1 / 2],
                         [transition_w2 / 2, -transition_w1 / 2]]);
        // Gauge section
        translate([x2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
