```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 130;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 30;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
gauge_x0 = -total_length/2 + grip_length + transition_len;       // gauge start X
gauge_x1 = gauge_x0 + gauge_length;                               // gauge end X

difference() {
    // Main body: union of grip, transition, and gauge sections
    union() {
        // Left grip
        translate([-total_length/2, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Central gauge
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            dx = transition_len / 2;
            translate([s > 0 ? gauge_x0 - dx : total_length/2 - grip_length - dx,
                       -grip_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-dx, -grip_width/2], [-dx, grip_width/2],
                             [dx, -gauge_width/2], [dx, gauge_width/2]]);
        }
    }

    // Notches along X, centred on each end of the gauge section
    for (x = gauge_x0 + gauge_length/2) {
        translate([x - eps, -gauge_width/2 - eps, -eps])
            cube([eps, gauge_width + 2*eps, thickness + 2*eps]);
    }
}
