// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 up to specimen thickness

// ---------------- Parameters ----------------
specimen_thickness   = 3;     // thickness (Z), mm
total_length         = 130;   // overall length along X, mm
gauge_width          = 6;     // gauge section width (Y), mm
gauge_length         = 50;    // gauge section length (X), mm
grip_width           = 19;    // grip section width (Y), mm
grip_length          = 25;    // grip section length (X), mm
transition_length    = 15;    // transition section length (X), mm
cut_extra            = 0.5;   // overshoot for clean boolean cuts, mm

$fn = 64;

// Derived: narrow end of transition (near gauge) and wide end (near grip)
transition_narrow_w = gauge_width  + (grip_width - gauge_width) * transition_length / (gauge_length + 2 * transition_length);
transition_wide_w   = grip_width   - (grip_width - gauge_width) * transition_length / (gauge_length + 2 * transition_length);

// ---------------- Model ----------------
difference() {
    union() {
        // Left grip
        translate([-total_length / 2 + grip_length + transition_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Right grip
        translate([total_length / 2 - grip_length - transition_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, specimen_thickness]);

        // Central gauge section
        translate([-total_length / 2 + grip_length + transition_length + gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, specimen_thickness]);

        // Left transition (width changes linearly from grip to gauge)
        translate([-total_length / 2 + grip_length, -transition_wide_w / 2, 0])
            linear_extrude(height = specimen_thickness)
                polygon([[-0, -transition_wide_w / 2], [-transition_length, -transition_narrow_w / 2],
                         [-transition_length, transition_narrow_w / 2], [0, transition_wide_w / 2]]);

        // Right transition (mirror of left)
        translate([total_length / 2 - grip_length - transition_length, -transition_wide_w / 2, 0])
            linear_extrude(height = specimen_thickness)
                polygon([[0, -transition_wide_w / 2], [transition_length, -transition_narrow_w / 2],
                         [transition_length, transition_narrow_w / 2], [-0, transition_wide_w / 2]]);
    }

    // Small cutouts at each end to avoid coplanar faces with the bed
    translate([-total_length / 2 - cut_extra, 0, -cut_extra])
        cube([cut_extra * 2, total_length, cut_extra * 2]);
}
