hw = grip_width / 2;              // grip half-width

// Sanity check on the given dimensions
assert(abs(2 * xe - total_length) < 1e-6,
       "Section lengths do not add up to total_length");

// ---- Model ----
linear_extrude(height = thickness)
    polygon(points = [
        [-xe, -hw], [-xt, -hw], [-xg, -hg], [ xg, -hg],
        [ xt, -hw], [ xe, -hw], [ xe,  hw], [ xt,  hw],
        [ xg,  hg], [-xg,  hg], [-xt,  hw], [-xe,  hw]
    ]);
