// Stiffened cover panel: flat plate with 4 transverse ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len      = 80;   // plate length along X
plate_wid      = 80;   // plate width along Y
plate_thk      = 2;    // plate thickness (z = 0 to 2)

rib_thk        = 2;    // rib thickness along X
rib_h          = 4;    // rib height above plate (z = 2 to 6)
rib_count      = 4;    // number of ribs
rib_pitch      = 16;   // centre-to-centre spacing of ribs
rib_offset     = 16;   // centre of outer rib to plate end

eps            = 0.5;  // overcut for clean boolean differences
$fn            = 64;   // curve resolution (no curves here, set per rules)

// Derived: distance between the two outer ribs (2 * pitch - 2 * offset)
rib_span       = 2 * rib_pitch - 2 * rib_offset;  // 32 mm

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on the plate lengthwise
    for (i = [0 : rib_count - 1]) {
        x_c = -rib_span/2 + i * rib_pitch;
        translate([x_c - rib_thk/2, -plate_wid/2, plate_thk])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
