plate_thk      = 2;     // plate thickness (z = 0 to 2)

rib_thk        = 2;     // rib thickness along X
rib_h          = 5;     // rib height above plate (z = 2 to 7)
rib_count      = 4;     // number of ribs
rib_pitch      = 24;    // centre-to-centre spacing of ribs
rib_offset     = 24;    // centre of outer rib from plate end

rib_embed      = 0.5;   // rib overlap into plate for a clean union

$fn = 64;               // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_t      = plate_thk + rib_embed;   // plate + embed depth (z = 0 to 2.5)
rib_top      = plate_thk + rib_h;       // top of ribs (z = 7)
rib_x        = [for (i = [0 : rib_count - 1])
                   rib_offset + i * rib_pitch - (rib_count - 1) * rib_pitch / 2]; // rib centre X

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, resting on z = 0
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_t]);

    // Ribs running full width along Y, centred on their X positions
    for (x = rib_x)
        translate([x - rib_thk / 2, -plate_wid / 2 - rib_embed, plate_thk])
            cube([rib_thk, plate_wid + 2 * rib_embed, rib_h]);
}
