// Powder measuring scoop - a hollow spherical bowl with a flat handle
// Print orientation: bowl bottom on the bed (z = 0), handle extending along +X

// ---------------- Parameters ----------------
bowl_outer_radius   = 10;   // outer radius of the spherical bowl
bowl_wall_thickness = 2;    // thickness of the bowl wall
bowl_centre         = 10;   // Z position of the sphere centre (0, 0, 10)
bowl_rim_z          = 10;   // Z height of the bowl rim (lower half, opens upward)
bowl_bottom_z       = 0;    // Z height of the bowl bottom, touching the bed

handle_width        = 12;   // handle width along Y
handle_thickness    = 3;    // handle thickness along Z
handle_top_z        = 7;    // handle top face Z (flush with rim, z = 7 to 10)
handle_x_start      = 8;    // handle start X position
handle_x_end        = 90;   // handle end X position

cut_overlap         = 0.5;  // extra length of cutters past faces to avoid coplanar faces
$fn                 = 96;   // curve resolution

// ---------------- Model ----------------
difference() {
    union() {
        // Hollow spherical bowl: lower half of a shell
        difference() {
            sphere(r = bowl_outer_radius, d = bowl_centre);
            translate([0, 0, bowl_centre - bowl_wall_thickness])
                sphere(r = bowl_outer_radius - 2 * bowl_wall_thickness, d = bowl_centre);
        }
        // Flat handle running along +X, centred on y = 0
        translate([handle_x_start, -handle_width / 2, handle_top_z])
            cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
    }

    // Cut the upper half of the sphere above the rim, leaving a clean opening
    translate([0, 0, bowl_rim_z])
        sphere(r = bowl_outer_radius + cut_overlap, d = bowl_centre + cut_overlap);
}
