// X positions of section boundaries, centred on origin
grip_inner_x   = (total_length - 2 * grip_length - 2 * transition_length) / 2;
gauge_start_x  = grip_inner_x + grip_length;
gauge_end_x    = gauge_start_x + gauge_length;
transition_end_x = gauge_end_x + transition_length;

// ---------------- Model ----------------
difference() {
    // Solid block covering full length and width of end grips
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width, specimen_thickness]);

    // Central gauge section (through-cut)
    translate([gauge_start_x - cut_extra, -gauge_width / 2, -cut_extra])
        cube([gauge_length + 2 * cut_extra, gauge_width, specimen_thickness + 2 * cut_extra]);

    // Two transition sections, width changing linearly from grip to gauge
    for (side = [-1, 1]) {
        x0 = grip_inner_x + grip_length;                      // gauge start
        x1 = x0 + transition_length;                          // transition end
        w0 = transition_start_w;
        w1 = transition_end_w;
        // keep one face coplanar with the grip block, cut into the gauge
        translate([x0 - cut_extra, -w0 / 2, -cut_extra])
            linear_extrude(height = transition_length + 2 * cut_extra)
                polygon([[-cut_extra, -w0 / 2], [cut_extra, -w0 / 2],
                         [cut_extra, w1 / 2], [-cut_extra, w1 / 2]]);
    }
