        translate([x0 + grip_x, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
        for (s = [-1, 1]) {
            translate([x0 + grip_x * s + grip_length - transition_len,
                       -trans_w(transition_len) / 2, 0])
                linear_extrude(thickness)
                    polygon([[-15, -trans_w(transition_len) / 2], [15, trans_w(transition_len) / 2]]);
        }
    }

    // Cutters along X, extended past both end faces
    for (x = [x0 - eps, x0 + total_length - eps])
        translate([x, -gauge_width / 2 - eps, -eps])
            cube([total_length + 2 * eps, gauge_width + 2 * eps, thickness + 2 * eps]);
