// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 15;    // transition section length (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
grip_area     = grip_width * grip_length * 2;  // both end grips
transition_area = 2 * transition_len * (grip_width + gauge_width) / 2;  // trapezoids
gauge_area    = gauge_width * gauge_length * thickness;
total_area    = grip_area + transition_area + gauge_area;

// ---------- Model ----------
difference() {
    // Solid block
    translate([-total_length / 2, -grip_width / 2, 0])
        cube([total_length, grip_width * 2, thickness]);

    // Cut out grips and transitions, leaving the gauge section
    for (s = [-1, 1]) {
        x0 = -total_length / 2 + grip_length;              // start of transition
        x1 = x0 + transition_len;                          // gauge start
        x2 = x1 + gauge_length + transition_len;           // end of transition
        x3 = x2 + grip_length;                             // end of specimen

        // Trapezoidal cutter, wider in Y at the grip ends
        translate([x0 - eps, -grip_width / 2 - eps, -eps])
            linear_extrude(height = thickness + 2 * eps)
                polygon([[-grip_width / 2, -transition_len / 2],
                         [-grip_width / 2, transition_len / 2],
                         [gauge_width / 2, transition_len / 2],
                         [gauge_width / 2, -transition_len / 2]]);

        // Rectangular grip cutter
        translate([x2, -grip_width / 2 - eps, -eps])
            cube([grip_length, grip_width * 2 + 2 * eps, thickness + 2 * eps]);
    }
}
