// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // cutter overshoot past faces
grip2 = grip_width - 2*eps;  // grip width reduced by overshoot (keeps same X span)

// ---- Model ----
difference() {
    union() {
        // Left grip
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Right grip
        translate([total_length/2 - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Central gauge
        translate([-total_length/2 + grip_length + transition_len,
                   -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Left transition (width changes linearly from grip to gauge)
        translate([-total_length/2 + grip_length, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[-0, -grip_width/2], [-0, grip_width/2],
                         [transition_len, gauge_width/2], [transition_len, -gauge_width/2]]);
        // Right transition
        translate([total_length/2 - grip_length - transition_len, -grip_width/2, 0])
            linear_extrude(thickness)
                polygon([[-0, -grip_width/2], [-0, grip_width/2],
                         [transition_len, gauge_width/2], [transition_len, -gauge_width/2]]);
    }
    // Cutters for grip and gauge sections, extended past faces
    translate([-total_length/2 + grip_length + 0.01, -grip2/2, -eps])
        cube([grip_length + 2*eps, grip2, thickness + 2*eps]);
    translate([total_length/2 - grip_length - 0.01, -grip2/2, -eps])
        cube([grip_length + 2*eps, grip2, thickness + 2*eps]);
    translate([-total_length/2 + grip_length + transition_len + 0.01,
               -gauge_width/2, -eps])
        cube([gauge_length + 2*eps, gauge_width, thickness + 2*eps]);
}
