// ---------------- Parameters ----------------
thickness      = 3;    // specimen thickness (Z)
total_length   = 140;  // overall length (X)
gauge_width    = 10;   // narrow gauge section width (Y)
gauge_length   = 40;   // gauge section length (X)
grip_width     = 19;   // grip section width (Y)
grip_length    = 35;   // grip section length (X), each end
trans_length   = 15;   // transition length (X), each side, linear taper

// ---------------- Derived ----------------
x_gauge = gauge_length / 2;              // end of gauge section (20)
x_trans = x_gauge + trans_length;        // end of transition (35)
x_end   = x_trans + grip_length;         // end of grip (70)
hg = gauge_width / 2;                    // half gauge width
hw = grip_width / 2;                     // half grip width

// Sanity check of total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not sum to total_length");

// ---------------- Outline (top view), counter-clockwise ----------------
outline = [
    [ x_end,  -hw], [ x_end,   hw],     // right grip end
    [ x_trans, hw], [ x_gauge, hg],     // right upper transition
    [-x_gauge, hg], [-x_trans, hw],     // left upper transition
    [-x_end,   hw], [-x_end,  -hw],     // left grip end
    [-x_trans,-hw], [-x_gauge,-hg],     // left lower transition
    [ x_gauge,-hg], [ x_trans,-hw]      // right lower transition
];

// ---------------- Model ----------------
linear_extrude(height = thickness)
    polygon(points = outline);
