```openscad
// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge

$fn = 64;

// ---------- Derived ----------
grip_x0 = -total_length/2 + grip_length;        // left grip start X
grip_x1 = total_length/2 - grip_length;         // right grip start X
gauge_x0 = grip_x0 + grip_length + transition_len;  // gauge start X
gauge_x1 = gauge_x0 + gauge_length;              // gauge end X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([grip_x1, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transitions (trapezoidal in Y)
        for (s = [-1, 1]) {
            x = grip_x0 + grip_length;  // transition start X
            dx = transition_len;
            // Y runs from grip_width/2 to gauge_width/2
            translate([x - dx/2, -grip_width/2, 0])
                linear_extrude([dx, thickness])
                    polygon([[-dx/2, -grip_width/2], [dx/2, -grip_width/2],
                              [dx/2, gauge_width/2], [-dx/2, gauge_width/2]]);
        }
    }

    // Small cutters to avoid coplanar faces
    translate([gauge_x0 - 0.5, -gauge_width/2 - 0.5, -0.5])
        cube([gauge_length + 1, gauge_width + 1, thickness + 1]);

    for (x = [grip_x0 + grip_length, grip_x1 + grip_length]) {
        translate([x - 0.5, -grip_width/2 - 0.5, -0.5])
            cube([transition_len + 1, grip_width + 1, thickness + 1]);
    }
}
