// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to z = thickness

// ---------- Parameters ----------
thickness      = 6;     // wheel thickness (mm)
outer_d        = 100;   // outer rim diameter (mm)
rim_width      = 6;     // rim width (mm)
hub_d          = 20;    // hub diameter (mm)
axle_d         = 6;     // axle hole diameter (mm)
spoke_count    = 4;     // number of spokes
spoke_width    = 5;     // spoke width (mm)
spoke_start_a  = 0;     // first spoke along +X axis (degrees)
eps            = 0.5;   // cutter overshoot past faces (mm)

$fn = 128;

// ---------- Derived ----------
inner_d = outer_d - 2 * rim_width;  // ring inner diameter (bore)

// ---------- Model ----------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_d, h = thickness);

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_a + i * 360 / spoke_count])
                translate([hub_d / 2, 0, 0])
                    cube([spoke_width, inner_d / 2 + 1, thickness]);
        }
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);

    // Bore through rim (between rim and hub)
    translate([0, 0, -eps])
        cylinder(d = inner_d, h = thickness + 2 * eps);
}
