flange_t = 2;    // bottom flange thickness (mm), z = 0 to 2
neck_w   = 8;    // neck width along Y (mm)
neck_h   = 4;    // neck height above flange (mm), z = 2 to 6
screw_d  = 3.4;  // central screw hole diameter (mm)
eps      = 0.5;  // cutter overshoot past faces (mm)

$fn = 64;

