            sphere(r = bowl_outer_radius);

        // Flat handle running along +X, centred on y = 0
        translate([handle_x_start, -handle_width / 2, handle_top_z])
            cube([handle_x_end - handle_x_start, handle_width, bowl_wall_thickness]);
    }

    // Cut the upper half of the sphere along the rim (z = 12)
    translate([0, 0, 12])
        cylinder(h = cut_extra, r = bowl_outer_radius);
}
