    union() {
        // Base plate
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) {
                translate([-plate_len/2 + i * seg_len - knuckle_d/2,
                           knuckle_y - knuckle_d/2,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2 * eps);
            }
        }
    }

    // Pin holes through every knuckle along the X axis
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([-plate_len/2 + i * seg_len - eps,
                       knuckle_y,
                       knuckle_z])
                translate([0, 0, -eps])
                    cylinder(d = knuckle_pin, h = plate_thk + 2 * eps);
        }
    }
