cut_ext     = 0.5;  // extension of cutters past faces

module knuckle(i) {
    // segment i (0-based) starts at x = -plate_len/2 + i*seg_len
    translate([-plate_len/2 + i*seg_len, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = knuckle_d, h = seg_len);
}

difference() {
    union() {
        // flat plate, centred on origin in XY
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // knuckles on 1st, 3rd and 5th segments (indices 0, 2, 4)
        for (i = [0 : 2 : n_segments - 1])
            knuckle(i);
    }

    // pin hole along the hinge axis through every knuckle
    translate([-plate_len/2 - cut_ext, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*cut_ext);
}
