// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// ---- Dimensions (mm) ----
thickness      = 3;     // specimen thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge

// ---- Derived ----
eps   = 0.5;            // overlap for clean boolean cuts
gauge = gauge_width;    // gauge section width (Y)

difference() {
    // Main body: grip + transition + gauge + transition + grip
    union() {
        for (s = [-1, 1]) {
            translate([s * (total_length / 2 - grip_length - transition_len), 0, 0])
                linear_extrude(thickness)
                    polygon([
                        [0, -grip_width / 2], [grip_length, -grip_width / 2],
                        [grip_length, grip_width / 2], [0, grip_width / 2]
                    ]);
        }
        translate([-grip_length - transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -grip_width / 2], [transition_len, -grip_width / 2],
                    [transition_len, gauge / 2], [0, gauge / 2]
                ]);
        translate([grip_length + transition_len, 0, 0])
            linear_extrude(thickness)
                polygon([
                    [0, -grip_width / 2], [transition_len, -grip_width / 2],
                    [transition_len, gauge / 2], [0, gauge / 2]
                ]);
    }

    // Central gauge section, cut through (eps past faces)
    translate([-gauge_length / 2, -eps, 0])
        linear_extrude(thickness + 2 * eps)
            rectangle([gauge_length, gauge]);
}
