// Flat tensile test specimen (dog bone) for FDM printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 100;   // overall length along X
gauge_width    = 10;    // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 15;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len = 10;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
grip_x0   = -total_length/2 + grip_length;      // left grip start X
gauge_x0  = grip_x0 + grip_length + transition_len;  // gauge start X
right_x0  = gauge_x0 + gauge_length + transition_len;       // right grip start X

// ---------- Model ----------
difference() {
    union() {
        // Left grip
        translate([grip_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Gauge section
        translate([gauge_x0, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);
        // Right grip
        translate([right_x0, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);
        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            dx = transition_len / 2;
            translate([gauge_x0 - dx * s, -gauge_width/2, 0])
                linear_extrude(thickness)
                    polygon([[-dx * s, -grip_width/2], [-dx * s, grip_width/2],
                              [dx * s, -gauge_width/2], [dx * s, gauge_width/2]]);
        }
    }
    // End cutters, extended past faces
    translate([grip_x0 - eps, -grip_width/2 - eps, -eps])
        cube([grip_length + 2*eps, grip_width + 2*eps, thickness + 2*eps]);
    translate([right_x0 + eps, -grip_width/2 - eps, -eps])
        cube([grip_length + 2*eps, grip_width + 2*eps, thickness + 2*eps]);
}
