total_length   = 130;   // overall length along X
gauge_width    = 6;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length along X
grip_width     = 20;    // grip section width (Y)
grip_length    = 35;    // grip section length along X
transition_len = 15;    // transition section length between grip and gauge
eps            = 0.5;   // cutter overshoot past faces

// ---- Derived ----
grip_start_x   = -total_length/2 + grip_length;   // grip start (left)
gauge_start_x  = grip_start_x + transition_len;   // gauge start
gauge_end_x    = gauge_start_x + gauge_length;    // gauge end
grip_end_x     = gauge_end_x + transition_len;    // right grip end

// ---- Model ----
difference() {
    // Solid body
    translate([-total_length/2, -grip_width/2, 0])
        cube([total_length, grip_width, thickness]);

    // Cut out the gauge section, extended into grips and transitions
    translate([grip_start_x - eps, -grip_width/2 - eps, -eps])
        cube([gauge_length + 2*transition_len + 2*eps,
              grip_width + 2*eps,
              thickness + 2*eps]);
}
