// ---------- Parameters ----------
wheel_thickness   = 8;     // rim/hub thickness (Z)
outer_diameter    = 60;    // outer rim diameter
rim_width         = 4;     // rim width (radial)
hub_diameter      = 14;    // central hub diameter
axle_hole_d       = 6;     // axle through-hole diameter
spoke_count       = 6;     // number of spokes
spoke_width       = 5;     // spoke width (radial)
cut_overlap       = 0.5;   // extra length of cutters past faces
$fn               = 96;    // curve resolution

// ---------- Derived ----------
inner_diameter = outer_diameter - 2 * rim_width;   // ring bore diameter
spoke_pitch    = 360 / spoke_count;                // angle between spokes

// ---------- Model ----------
difference() {
    // Outer body: rim + hub
    union() {
        cylinder(d = outer_diameter, h = wheel_thickness);
        cylinder(d = hub_diameter, h = wheel_thickness);
    }

    // Axle hole through hub (and slightly into rim)
    translate([0, 0, -cut_overlap])
        cylinder(d = axle_hole_d, h = wheel_thickness + 2 * cut_overlap);

    // Spokes cut from rim, running radially from hub to outer edge
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, i * spoke_pitch])
            translate([hub_diameter / 2, 0, -cut_overlap])
                cube([spoke_width,
                       (outer_diameter / 2 - hub_diameter / 2) + cut_overlap,
                       wheel_thickness + 2 * cut_overlap]);
    }
}
